REPO=Path(__file__).resolve().parents[1]
ROOT=REPO/'artifacts/memory-task-project-20261030'
LEDGER=REPO/'artifacts/memory-reuse-loop-20261026/attempts.json'
NODE=str(Path(shutil.which('node')).resolve());MODEL='claude-sonnet-5-5';CHANNEL='project_task_work_v1';CAP=437;LIMIT=3.60
HELPER=REPO/'scripts/memory-reuse-claude.mjs';HOST=REPO/'scripts/memory-task-project-host.mjs'
SYSTEM='This is a real, bounded documentation task for this project. Use only the exact configured Bash run command supplied by the UserPromptSubmit hook. Current source is already provided by the host. Do not run discovery, other shell commands, agents, MCP, or services. For patch generate only approved new sections; the host keeps prior sections exactly. For write generate all requested sections. Write useful Japanese deliverables, about 300-700 Japanese characters per section, cite the original relative paths, preserve measured values and units, and distinguish historical synthetic measurements from new real human work. Never claim unobserved savings, real team adoption or billing. Do not ask another scope question. Finish with only the deliverable path and a short status.'
def load(p,default=None):return json.loads(p.read_text()) if p.exists() else default
def save(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rows(p):return [json.loads(x) for x in p.read_text().splitlines() if x.strip()] if p.exists() else []
def config():return load(REPO/'.local/memory-reuse/config.json')
def state(sid):return load(REPO/'.local/memory-reuse/task-confirmations'/(sid+'.json'))
def host(operation,request,receipt=None):
 started=time.monotonic()
 p=subprocess.run([NODE,str(HOST),operation,str(request)]+([str(receipt)] if receipt else []),cwd=REPO,env=environment(),capture_output=True,text=True,timeout=60)
 if p.returncode:raise RuntimeError(p.stderr[-2000:])
 return {**json.loads(p.stdout),'host_process_elapsed_ms':(time.monotonic()-started)*1000}
def environment():return {**os.environ,'ORGBRAIN_REUSE_ROOT':str(REPO),'ORGBRAIN_USE_PRINCIPAL':'local'}
def prepare():
 ROOT.mkdir(parents=True,exist_ok=True)
 if not (ROOT/'budget-proposal.json').exists():save(ROOT/'budget-proposal.json',{'approved_additional_max':18,'approved_cumulative_cap':CAP,'approved_api_equivalent_usd':LIMIT,'estimated_api_equivalent_usd':1.80,'approval_question_call_id':'call_d13bbac9a909470c95c9b343b2ad79a7','prior_cumulative':419,'actual_billing_usd':None,'parent_implementation_cost':None,'cloud_deploy':False})
 c=config();files={'scripts/memory-reuse-claude.mjs','scripts/memory-task-project-host.mjs','scripts/memory-reuse-task-local.mjs','scripts/memory-task-document-adapter.mjs'}
 for w in c['task_workflows'].values():
  if w.get('source_mode')=='project_files':files.update(w['source_files']);files.update(str(Path(p).relative_to(REPO)) for p in w.get('dependency_files',[]))
 manifest={p:sha(REPO/p) for p in sorted(files)}
 if not (ROOT/'manifest.json').exists():
  save(ROOT/'manifest.json',manifest);save(ROOT/'project-config.json',c)
  for name in files:
   destination=ROOT/'originals'/name;destination.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(REPO/name,destination)
 else:
  if manifest!=load(ROOT/'manifest.json'):
   attempts=[x for x in load(LEDGER) if x.get('channel')==CHANNEL]
   resolved=load(ROOT/'resolved-failures.json',{}).get('attempts',[])
   old=load(ROOT/'manifest.json');changed={p for p in set(old)|set(manifest) if old.get(p)!=manifest.get(p)}
   scenario_change=changed.issubset({'scripts/memory-task-project-host.mjs'}) and load(ROOT/'method-change.json',{}).get('raw_user_instruction')=='全パターン実行して'
   if not scenario_change and any(x.get('success') or x.get('failure_reason')!='cli_not_authenticated' and x['id'] not in resolved for x in attempts):raise RuntimeError('project_sources_or_implementation_changed_before_evaluation')
   oldsha=sha(ROOT/'manifest.json');save(ROOT/'manifest-history'/(oldsha+'.json'),load(ROOT/'manifest.json'));shutil.move(str(ROOT/'originals'),str(ROOT/'manifest-history'/('originals-'+oldsha)));save(ROOT/'manifest.json',manifest)
   for name in files:
    destination=ROOT/'originals'/name;destination.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(REPO/name,destination)
 if not (ROOT/'cases.json').exists():
  cases=[]
  for kind in ['research','analysis','document']:
   wid='project-'+kind;w=c['task_workflows'][wid];units=w['default_units']
   for i,selected in enumerate([units[:2],units]):cases.append({'id':kind+'-'+str(i+1),'kind':kind,'workflow':wid,'units':selected,'assignment':w['assignment'],'intended_opportunity':'existing' if i==0 else 'delta'})
  save(ROOT/'cases.json',cases)
 return c
def request_for(case,condition,phase='comparison'):
 path=ROOT/'requests'/(phase+'-'+case['id']+'-'+condition+'.json')
 if path.exists():return path,load(path)
 request={'session_id':str(uuid.uuid4()),'observation_origin':'solicited','comparison_condition':condition,'prompt':case['assignment']+'\n対象の各単位だけを取り扱い、元資料にない事実は加えないでください。\n<reuse_task>'+json.dumps({'workflow':case['workflow'],'units':case['units']},ensure_ascii=False,separators=(',',':'))+'</reuse_task>'}
 save(path,request);return path,request
def ensure_prepared(case,condition,phase='comparison'):
 path,request=request_for(case,condition,phase);outpath=ROOT/'prepared'/(request['session_id']+'.json')
 existed=outpath.exists()
 if not existed:save(outpath,host('prepare',path))
 return path,request,{**load(outpath),'_prepared_before_this_call':existed}
def accounting(result):
 models=result.get('modelUsage');keys={'input_tokens':'inputTokens','cache_creation_input_tokens':'cacheCreationInputTokens','cache_read_input_tokens':'cacheReadInputTokens','output_tokens':'outputTokens'}
 if not isinstance(models,dict) or list(models)!=[MODEL] or any(type(models[MODEL].get(k)) is not int or models[MODEL][k]<0 for k in keys.values()):return None,None
 usage={k:models[MODEL][v] for k,v in keys.items()};return sum(usage.values()),usage
def audit_native(events,s,d):
 native=[b for e in events if e.get('type')=='assistant' for b in e.get('message',{}).get('content',[]) if b.get('type')=='tool_use']
 outputs={b['tool_use_id']:b for e in events if e.get('type')=='user' for b in e.get('message',{}).get('content',[]) if b.get('type')=='tool_result'}
 checks=[]
 for b in native:
  try:
   argv=shlex.split(b['input']['command']);assert b['name']=='Bash' and len(argv)==4 and argv[:3]==[NODE,str(HELPER),'run']
   request=json.loads(argv[3]);assert request['task_id']==s['task_id'] and request['adapter']==s['adapter']
   out=outputs[b['id']];assert not out.get('is_error');value=json.loads(out['content']);p=REPO/'.local/memory-reuse/invocations'/(value['reuse_invocation_id']+'.json');private=load(p)
   assert private['request']==request and private['native_call_id']==b['id'] and private['output']==value
   shutil.copyfile(p,d/('invocation-'+value['reuse_invocation_id']+'.json'))
   x=request['input'];expected='patch' if s['choice']=='delta' else 'write';assert x['op']==expected and sorted(x['units'])==sorted(s['allowed_units'])
   if expected=='patch':assert all(private['output']['artifact']['sections'][u]==s['prior']['sections'][u] for u in s['requested_units'] if u not in s['allowed_units'])
   checks.append(True)
  except (ValueError,KeyError,AssertionError,TypeError,FileNotFoundError):checks.append(False)
 return bool(checks) and all(checks),len(native)
def run_one(case,condition,phase='comparison'):
 setup_started=time.monotonic()
 prepare();records=load(LEDGER);label=phase+'-'+case['id']+'-'+condition
 previous=[x for x in records if x.get('channel')==CHANNEL and x.get('label')==label]
 if previous and previous[-1].get('success'):return previous[-1]
 auth=subprocess.run(['claude','auth','status'],cwd=REPO,env=environment(),capture_output=True,text=True,timeout=20)
 try:authenticated=json.loads(auth.stdout).get('loggedIn') is True
 except ValueError:authenticated=False
 save(ROOT/'auth-status.json',{'logged_in':authenticated,'exit_code':auth.returncode,'checked_at':time.time(),'model_starts':0})
 if not authenticated:raise RuntimeError('login_required_no_model_retry')
 if previous:
  resolved=load(ROOT/'resolved-failures.json',{}).get('attempts',[])
  if previous[-1].get('failure_reason')!='cli_not_authenticated' and previous[-1]['id'] not in resolved:raise RuntimeError('retained_failure_requires_diagnosis_before_new_attempt')
  oldpath,oldrequest=request_for(case,condition,phase);destination=ROOT/'retired-requests'/(oldrequest['session_id']+'.json');destination.parent.mkdir(exist_ok=True);shutil.move(str(oldpath),str(destination))
 current=[x for x in records if x.get('channel')==CHANNEL]
 if len(current)>=18 or len(records)>=CAP or any(x.get('api_equivalent_usd') is None for x in current) or sum(x['api_equivalent_usd'] for x in current)+0.25>LIMIT:raise RuntimeError('evaluation_budget_stop')
 path,request,prep=ensure_prepared(case,condition,phase);sid=request['session_id'];s=state(sid);answer_prepared_here=False
 if s['choice']=='pending' and condition=='reuse' and load(ROOT/'method-change.json',{}).get('raw_user_instruction')=='全パターン実行して':
  directive=load(ROOT/'method-change.json');receipt={**directive,'provenance':'user_requested_scenario','session_id':sid,'answer':{'existing':'既存成果で完了','delta':'差分だけ実施','full':'全体を実施'}[case['intended_opportunity']],'response_window_ms':directive['instruction_response_window_upper_bound_ms']};destination=ROOT/'human-answers'/(sid+'.json');save(destination,receipt);save(ROOT/'answered'/(sid+'.json'),host('scenario-answer',path,destination));s=state(sid);answer_prepared_here=True
 if s['choice'] not in ['full','delta']:raise RuntimeError('actual_human_answer_required_before_model_work')
 if not s.get('local',{}).get('source'):raise RuntimeError('host_source_not_prepared')
 packet=load(ROOT/'answered'/(sid+'.json'),{}) if condition=='reuse' else prep
 envelope=Path(packet['source_envelope_path']).read_text();env=environment();env['ORGBRAIN_TASK_SOURCE_ENVELOPE_DIGEST']=packet['source_envelope_digest']
 recovery=' The uses:[] attribution field must be a root-level peer of task_id, adapter and input. Never put uses inside input.' if previous and previous[-1].get('failure_reason')=='root_uses_missing' else ''
 argv=['claude','-p','--input-format','stream-json','--output-format','stream-json','--verbose','--include-hook-events','--model',MODEL,'--effort','medium','--tools','Bash','--allowedTools','Bash','--strict-mcp-config','--mcp-config','{"mcpServers":{}}','--setting-sources','project,local','--disable-slash-commands','--max-budget-usd','0.20','--session-id',sid,'--append-system-prompt',SYSTEM+recovery+'\n'+envelope]
 a={'id':'claude:'+sid,'label':label,'channel':CHANNEL,'case':case['id'],'kind':case['kind'],'condition':condition,'phase':phase,'units':case['units'],'origin':'solicited','workspace':str(REPO),'model_requested':MODEL,'effort':'medium','argv':argv,'prompt_sha256':hashlib.sha256(request['prompt'].encode()).hexdigest(),'sources_manifest_sha256':sha(ROOT/'manifest.json'),'driver_sha256':sha(Path(__file__))}
 a['source_envelope_digest']=packet['source_envelope_digest'];host('model-start',path)
 extra=prep.get('host_process_elapsed_ms',0) if prep['_prepared_before_this_call'] else 0
 if condition=='reuse' and not answer_prepared_here:extra+=packet['host_process_elapsed_ms']
 a['setup_ms']=(time.monotonic()-setup_started)*1000+extra;a['setup_accounting']='entire current setup plus prior offer/answer host processes; excludes human window and separately measured offline audit'
 d=ROOT/'runs'/a['id'];records=execute_cli(argv,request['prompt'],REPO,env,d,LEDGER,a,CAP);events=rows(d/'events.jsonl');result=next((x for x in reversed(events) if x.get('type')=='result'),{});s=state(sid);observation=load(REPO/'.local/memory-reuse/last-observation.json',{});completion=observation.get('task_completion') or {};tokens,usage=accounting(result);matched,native_count=audit_native(events,s,d)
 errors=[x for x in events if x.get('subtype')=='hook_response' and x.get('exit_code')!=0]
 good=a['returncode']==0 and not a['timeout'] and not result.get('is_error') and completion.get('status')==('completed_delta' if s['choice']=='delta' else 'completed_full') and matched and not errors and tokens is not None
 a.update(status='observed' if good else 'observed_failed',success=good,total_tokens=tokens,usage=usage,model_usage=result.get('modelUsage'),api_equivalent_usd=result.get('total_cost_usd'),actual_billing_usd=None,task_completion=completion,native_arguments_match=matched,native_bash_calls=native_count,model_responses=len({e['message']['id'] for e in events if e.get('type')=='assistant'}),hook_errors=errors,total_ms=a['setup_ms']+a['cli_ms'],actual_human_choice=s.get('decision_source'),failure_reason='cli_not_authenticated' if result.get('result')=='Not logged in · Please run /login' else None)
 save(d/'result.json',result);save(d/'state.json',s);save(d/'observation.json',observation);save(d/'outcome.json',a);save(LEDGER,records)
 if s['created_results']:
  artifact=s['created_results'][-1];shutil.copyfile(REPO/artifact['path'],d/'deliverable.md');a['artifact_path']=artifact['path'];save(d/'outcome.json',a);save(LEDGER,records)
 print(json.dumps({k:a[k] for k in ['label','success','total_tokens','total_ms','api_equivalent_usd','task_completion']},ensure_ascii=False),flush=True)
 if not good:raise RuntimeError('retain_model_failure_no_automatic_retry')
