def seeds():
 prepare()
 for case in load(ROOT/'cases.json'):
  if case['intended_opportunity']=='existing':run_one(case,'control','seed')
def offers():
 prepare();out=[]
 for case in load(ROOT/'cases.json'):
  path,request,prep=ensure_prepared(case,'reuse');assert prep['question'],'No real prior result available'
  out.append({**case,**prep,'request_path':str(path.relative_to(REPO)),'session_id':request['session_id']})
 save(ROOT/'human-offers.json',out);print(json.dumps(out,ensure_ascii=False,indent=2))
def controls():
 for case in load(ROOT/'cases.json'):run_one(case,'control')
def accept(path):
 batch=load(path);assert batch.get('provenance')=='native_user_answer'
 for offer in load(ROOT/'human-offers.json'):
  answer=next((x for x in batch['answers'] if x['case']==offer['id']),None)
  if not answer:continue
  request_path=REPO/offer['request_path'];sid=offer['session_id'];receipt={**answer,'provenance':batch['provenance'],'question_call_id':batch['question_call_id'],'question_digest':hashlib.sha256(offer['question']['question'].encode()).hexdigest(),'session_id':sid,'response_window_ms':batch['response_window_ms']}
  destination=ROOT/'human-answers'/(sid+'.json');save(destination,receipt);result=host('answer',request_path,destination);save(ROOT/'answered'/(sid+'.json'),result);print(json.dumps({'case':offer['id'],'choice':answer['answer'],'result':result},ensure_ascii=False))
def reuse_runs():
 for case in load(ROOT/'cases.json')+load(ROOT/'scenario-cases.json',[]):
  _,request,_=ensure_prepared(case,'reuse');s=state(request['session_id'])
  if s['choice']=='existing':continue
  run_one(case,'reuse')
def scenarios():
 directive=load(ROOT/'method-change.json');assert directive['raw_user_instruction']=='全パターン実行して'
 prepare();base=load(ROOT/'cases.json');extra=[{**case,'id':case['kind']+'-full','baseline_case':case['id'],'intended_opportunity':'full'} for case in base if case['intended_opportunity']=='delta'];save(ROOT/'scenario-cases.json',extra)
 for case in base+extra:
  path,request,offer=ensure_prepared(case,'reuse');assert offer['question']
  answer={'existing':'既存成果で完了','delta':'差分だけ実施','full':'全体を実施'}[case['intended_opportunity']]
  receipt={**directive,'provenance':'user_requested_scenario','session_id':request['session_id'],'answer':answer,'response_window_ms':directive['instruction_response_window_upper_bound_ms']};destination=ROOT/'human-answers'/(request['session_id']+'.json');save(destination,receipt)
  result=host('scenario-answer',path,destination);save(ROOT/'answered'/(request['session_id']+'.json'),result);print(json.dumps({'case':case['id'],'scenario':answer,'model_starts':0,'decision_is_natural_adoption':False},ensure_ascii=False))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('action',choices=['prepare','seed','offers','controls','accept','reuse','scenarios']);p.add_argument('--answers',type=Path);a=p.parse_args()
 if a.action=='prepare':prepare();print(json.dumps({'model_starts':0,'cumulative':len(load(LEDGER))}))
 elif a.action=='seed':seeds()
 elif a.action=='offers':offers()
 elif a.action=='controls':controls()
 elif a.action=='accept':accept(a.answers)
 elif a.action=='reuse':reuse_runs()
 elif a.action=='scenarios':scenarios()
